#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using Oculus.Interaction;using Oculus.Interaction.HandGrab;using Oculus.Interaction.Editor.QuickActions;using Oculus.Interaction.Editor.UnityXR.QuickActions;
namespace VRMaintenanceResearch.HandsLabQuest3.Editor {
public static partial class HandsLabEditor {
const string SDK="Packages/com.meta.xr.sdk.interaction";
static partial void RunLabCommand(string command){if(command=="sdk_probe")SdkProbe();else if(command=="build_scene")BuildScene();else RuntimeCommand(command);}
static partial void RuntimeCommand(string command);
static string PathOf(Transform t){return t.parent?PathOf(t.parent)+"/"+t.name:t.name;}
static void SdkProbe(){Guard();string source=SDK+"/Samples~/UnityXR/Scenes/UnityXRComprehensiveRigExample.unity";string dest=Root+"/Editor/ReferenceSample.unity";if(!File.Exists(dest)){File.Copy(source,dest);AssetDatabase.ImportAsset(dest);}var s=EditorSceneManager.OpenScene(dest,OpenSceneMode.Additive);try {Write("sdk_sample_objects",s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.GetComponent<Rigidbody>()||t.GetComponent<HandGrabInteractable>()||t.GetComponent<Grabbable>()).Select(t=>new{path=PathOf(t),name=t.name,position=new[]{t.position.x,t.position.y,t.position.z},scale=new[]{t.lossyScale.x,t.lossyScale.y,t.lossyScale.z},body=t.GetComponent<Rigidbody>()!=null,poses=t.GetComponentsInChildren<HandGrabPose>(true).Length,types=t.GetComponents<Component>().Where(c=>c).Select(c=>c.GetType().FullName).ToArray()}));}finally{EditorSceneManager.CloseScene(s,true);} }
static void BuildScene(){Guard();if(File.Exists(ScenePath))throw new Exception("HandsLab scene exists; not overwritten");var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("HandsLab_Quest3");UnityXRQuickActionsAPI.AddUnityXRInteractionRig(false);var origin=UnityEngine.Object.FindFirstObjectByType<Unity.XR.CoreUtils.XROrigin>();origin.transform.SetParent(root.transform,true);origin.transform.position=Vector3.zero;origin.transform.rotation=Quaternion.identity;foreach(var t in origin.GetComponentsInChildren<Transform>(true)){if(t.name.Contains("Teleport")||t.name.Contains("Locomotion")||t.name.Contains("DistanceGrab")||t.name.Contains("RayGrab"))t.gameObject.SetActive(false);}var light=new GameObject("HandsLab_KeyLight").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.transform.rotation=Quaternion.Euler(50,-35,0);light.transform.SetParent(root.transform);RenderSettings.ambientLight=new Color(.48f,.53f,.60f);Cube("Floor",new Vector3(0,-.05f,0),new Vector3(4,.1f,4),new Color(.13f,.17f,.22f),root.transform);Cube("Table",new Vector3(0,.72f,.62f),new Vector3(1.15f,.06f,.62f),new Color(.33f,.40f,.45f),root.transform);Cube("Placement",new Vector3(0,.754f,.70f),new Vector3(.38f,.008f,.24f),new Color(.12f,.55f,.55f),root.transform);var panel=HandsLabPanel.Build(root.transform);panel.transform.localPosition=new Vector3(0,1.22f,.93f);panel.transform.localRotation=Quaternion.Euler(0,180,0);QuickActionsAPI.AddRayCanvasInteraction(panel.gameObject);QuickActionsAPI.AddPokeCanvasInteraction(panel.gameObject);Write("rig_structure",origin.GetComponentsInChildren<Transform>(true).Select(t=>new{path=PathOf(t),active=t.gameObject.activeSelf,types=t.GetComponents<Component>().Where(c=>c).Select(c=>c.GetType().FullName).ToArray()}));EditorSceneManager.SaveScene(s,ScenePath);File.Copy(ScenePath,Out+"/MODIFIED_FILE.unity",true);Probe();}
static GameObject Cube(string name,Vector3 position,Vector3 scale,Color color,Transform parent){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent);g.transform.position=position;g.transform.localScale=scale;var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=color;string dir=Root+"/Materials";if(!Directory.Exists(dir))Directory.CreateDirectory(dir);string path=dir+"/"+name+".mat";AssetDatabase.CreateAsset(mat,path);g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
}}
#endif

